      s += body(c, cup, k, L < 0 ? 'M2,-11 L5,-11 L3.8,-3 Q2.6,-2.3 1.6,-2.1 Z' : 'M-2,-11 L-5,-11 L-3.8,-3 Q-2.6,-2.3 -1.6,-2.1 Z', L < 0 ? 'M-4.2,-10 L-3.6,-10 L-2.7,-4 L-3.2,-4 Z' : 'M4.2,-10 L3.6,-10 L2.7,-4 L3.2,-4 Z');
      s += body(c, ellD(0, -11, 5, 1.3), { base: k.hi, shade: k.shade, hi: k.hi, ink: k.ink }, null, null) + ell(0, -10.9, 4.1, 0.9, c.col(c.pal.coffee));
