      var gl = poly([[-6, -3], [6, -3], [5, -19], [-5, -19]]);
      s += fill(gl, glass.base);
      if (o.lit) s += ell(0, -10, 2.4, 4.2, c.col(c.pal.flame)) + ell(0, -9, 1.2, 2.4, c.col(light(c.pal.flame, 0.6)));
      s += fill(poly(L < 0 ? [[2.5, -3], [6, -3], [5, -19], [2.2, -19]] : [[-2.5, -3], [-6, -3], [-5, -19], [-2.2, -19]]), glass.shade, ' opacity="0.55"');
