      var bd = 'M-12,-1 C-15.5,-12 -15.5,-23 -12,-34 L12,-34 C15.5,-23 15.5,-12 12,-1 Q0,2 -12,-1 Z';
      var sh = L < 0 ? 'M6,-34 L12,-34 C15.5,-23 15.5,-12 12,-1 Q9,0 6,0.4 C8,-12 8,-23 6,-34 Z' : 'M-6,-34 L-12,-34 C-15.5,-23 -15.5,-12 -12,-1 Q-9,0 -6,0.4 C-8,-12 -8,-23 -6,-34 Z';
